```python
def print_board(board):
    """Print the game board in a readable format."""
    for row in board:
        print(' | '.join(str(cell) for cell in row))
        print('-' * 9)

def get_user_move():
    """Get user input for a move on the game board."""
    while True:
        try:
            move = int(input("Enter your move (e.g., 1 2): "))
            row, col = divmod(move - 1, 3)
            return row, col
        except ValueError:
            print("Invalid input. Please enter a number between 1 and 9.")

def is_valid_move(board, row, col):
    """Check if the given row and column are valid for the game board."""
    return 0 <= row < 3 and 0 <= col < 3 and board[row][col] == 0

def make_move(board, row, col, player):
    """Make a move on the game board and update the player's moves."""
    board[row][col] = player
    player = 'X' if player == 'O' else 'O'
    return board, player

def check_winner(board):
    """Check for a winner on the game board."""
    for row in board:
        if row[0] != 0 or row[1] != 0 or row[2] != 0:
            return row[0], row[1], row[2]

    for col in range(3):
        if board[0][col] != 0 or board[1][col] != 0 or board[2][col] != 0:
            return board[0][col], board[1][col], board[2][col]

    if board[0][0] != 0 or board[1][1] != 0 or board[2][2] != 0:
        return board[0][0], board[1][1], board[2][2]

    if board[0][2] != 0 or board[1][1] != 0 or board[2][0] != 0:
        return board[0][2], board[1][1], board[2][0]

    return None

def play_tic_tac_toe():
    """Play a game of Tic-Tac-Toe with the user."""
    board = [[' '] * 3 for _ in range(3)]
    player = 'O'

    while True:
        print_board(board)
        row, col = get_user_move()
        if not is_valid_move(board, row, col):
            print("Invalid move. Please try again.")
            continue

        board, player = make_move(board, row, col, player)

        winner = check_winner(board)
        if winner:
            print_board(board)
            print(f"You won! The final board is:")
            print_board(board)
            break

        if ' ' not in ''.join(''.join(row) for row in board):
            print_board(board)
            print("It's a tie. The final board is:")
            print_board(board)
            break

play_tic_tac_toe()
